/* -------------------------------------------------------------------
 * 7. GRANDMASTER 4-TIER AI ENGINE + ANTI-LOOP + ADAPTIVE BRAIN + PUTER AI
 * ------------------------------------------------------------------- */
let MorrisTT = new Map();
let MorrisKillerMoves = [];
let MorrisHistoryTable = { 1: new Int32Array(600), 2: new Int32Array(600) };
let morrisSearchDeadline = 0;
let morrisSearchAborted = false;
let morrisLastRuleSig = '';

let _cachedMorrisLinesRef = null;
let NodeMillPairs = [];
let NodeDegreeWeights = [];

function ensureMorrisTopologyCache() {
  if (_cachedMorrisLinesRef === MillLines && NodeMillPairs.length === Nodes.length) {
    return;
  }
  _cachedMorrisLinesRef = MillLines;
  NodeMillPairs = Array.from({ length: Nodes.length }, () => []);
  NodeDegreeWeights = new Int32Array(Nodes.length);
  for (let lineIdx = 0; lineIdx < MillLines.length; lineIdx++) {
    const [a, b, c] = MillLines[lineIdx];
    if (a < Nodes.length && b < Nodes.length && c < Nodes.length) {
      NodeMillPairs[a].push([b, c, lineIdx]);
      NodeMillPairs[b].push([a, c, lineIdx]);
      NodeMillPairs[c].push([a, b, lineIdx]);
    }
  }
  for (let i = 0; i < Nodes.length; i++) {
    const deg = Adjacency[i] ? Adjacency[i].size : 2;
    const mCount = NodeMillPairs[i].length;
    NodeDegreeWeights[i] = deg * 12 + mCount * 14;
  }
}

function getMorrisRuleSignature() {
  return `${GameState.gridPreset}|${GameState.morrisDiagonals ? 1 : 0}|${GameState.piecesPerPlayer}|${GameState.morrisDropOrder}|${GameState.morrisDropMillRule}|${GameState.morrisMillRemovalRule}|${GameState.morrisFlyingRule}`;
}

function fastCountMillsAtNode(nodeId, player, board) {
  ensureMorrisTopologyCache();
  if (board[nodeId] !== player) return 0;
  const pairs = NodeMillPairs[nodeId];
  if (!pairs) return 0;
  let count = 0;
  for (let i = 0; i < pairs.length; i++) {
    const p = pairs[i];
    if (board[p[0]] === player && board[p[1]] === player) count++;
  }
  return count;
}

function fastWouldCompleteMill(nodeId, player, board) {
  ensureMorrisTopologyCache();
  const pairs = NodeMillPairs[nodeId];
  if (!pairs) return 0;
  let count = 0;
  for (let i = 0; i < pairs.length; i++) {
    const p = pairs[i];
    if (board[p[0]] === player && board[p[1]] === player) count++;
  }
  return count;
}

// 8-Fold Dihedral Symmetry Engine for 24-Node, 16-Node & 9-Node Morris Boards
const MorrisSymmetry = {
  mapsByPreset: {},
  ensureMaps() {
    const preset = GameState.gridPreset || 'navakankari_9';
    const nLen = Nodes ? Nodes.length : 0;
    const cacheKey = `${preset}_${nLen}`;
    if (this.mapsByPreset[cacheKey]) return this.mapsByPreset[cacheKey];
    if (!Nodes || nLen === 0 || GameState.gameFamily !== 'morris') return null;
    const maxCoord = nLen === 9 ? 2 : (nLen === 16 ? 4 : 6);
    const coordToId = new Map();
    for (let i = 0; i < nLen; i++) {
      coordToId.set(`${Math.round(Nodes[i].r)},${Math.round(Nodes[i].c)}`, i);
    }
    const transforms = [
      (r, c) => [r, c],
      (r, c) => [c, maxCoord - r],
      (r, c) => [maxCoord - r, maxCoord - c],
      (r, c) => [maxCoord - c, r],
      (r, c) => [r, maxCoord - c],
      (r, c) => [maxCoord - r, c],
      (r, c) => [c, r],
      (r, c) => [maxCoord - c, maxCoord - r]
    ];
    const maps = [];
    for (const tf of transforms) {
      const perm = new Array(nLen);
      let valid = true;
      for (let i = 0; i < nLen; i++) {
        const [nr, nc] = tf(Math.round(Nodes[i].r), Math.round(Nodes[i].c));
        const mapped = coordToId.get(`${nr},${nc}`);
        if (mapped === undefined) {
          valid = false;
          break;
        }
        perm[i] = mapped;
      }
      if (valid) maps.push(perm);
    }
    if (maps.length === 8) {
      this.mapsByPreset[cacheKey] = maps;
      return maps;
    }
    return null;
  },

  transformNode(nodeId, symIdx) {
    const maps = this.ensureMaps();
    if (!maps || nodeId < 0 || nodeId >= maps[0].length) return nodeId;
    return maps[symIdx % 8][nodeId];
  },

  canonicalizeStateAndAction(board, action, aiP) {
    const maps = this.ensureMaps();
    const nLen = board.length;
    if (!maps || maps[0].length !== nLen) {
      let raw = '';
      for (let i = 0; i < nLen; i++) {
        const v = board[i];
        raw += v === 0 ? '0' : (v === aiP ? '1' : '2');
      }
      const aStr = !action ? '' : (action.type === 'drop' ? `d:${action.to}` : (action.type === 'step' ? `s:${action.from}>${action.to}` : `r:${action.capturedId}`));
      return { stateKey: raw, actionKey: aStr };
    }
    let bestBoardStr = null;
    let bestActStr = '';
    for (let s = 0; s < 8; s++) {
      const perm = maps[s];
      const inv = new Array(nLen);
      for (let i = 0; i < nLen; i++) inv[perm[i]] = i;
      let bStr = '';
      for (let j = 0; j < nLen; j++) {
        const v = board[inv[j]];
        bStr += v === 0 ? '0' : (v === aiP ? '1' : '2');
      }
      let aStr = '';
      if (action) {
        if (action.type === 'drop') aStr = `d:${perm[action.to]}`;
        else if (action.type === 'step') aStr = `s:${perm[action.from]}>${perm[action.to]}`;
        else if (action.type === 'remove_opponent') aStr = `r:${perm[action.capturedId]}`;
      }
      if (bestBoardStr === null || bStr < bestBoardStr || (bStr === bestBoardStr && aStr < bestActStr)) {
        bestBoardStr = bStr;
        bestActStr = aStr;
      }
    }
    return { stateKey: bestBoardStr, actionKey: bestActStr };
  }
};

// Anti-Loop & Oscillation Prevention Tracker across ALL games
const LoopTracker = {
  stateCounts: new Map(),
  stateSequence: [],
  playerMoves: { 1: [], 2: [] },
  nonProgressPlies: 0,

  reset() {
    this.stateCounts.clear();
    this.stateSequence = [];
    this.playerMoves = { 1: [], 2: [] };
    this.nonProgressPlies = 0;
  },

  computeSignature(board, reserves, kings) {
    let s = '';
    for (let i = 0; i < board.length; i++) s += board[i];
    const r1 = (reserves && reserves[1]) || 0;
    const r2 = (reserves && reserves[2]) || 0;
    s += `|${r1},${r2}`;
    if (kings && GameState.gameFamily === 'dama') {
      s += '|';
      for (let i = 0; i < kings.length; i++) s += kings[i] ? '1' : '0';
    }
    return s;
  },

  recordAction(player, action, boardAfter, reservesAfter, kingsAfter, isIrreversibleProgress = false) {
    if (isIrreversibleProgress || !action || action.type === 'drop' || action.type === 'jump' || action.type === 'remove_opponent') {
      this.nonProgressPlies = 0;
      this.playerMoves = { 1: [], 2: [] };
      this.stateCounts.clear();
    } else {
      this.nonProgressPlies++;
      if (action.from !== undefined && action.from >= 0 && action.to !== undefined && action.to >= 0) {
        const list = this.playerMoves[player] || (this.playerMoves[player] = []);
        list.push({ from: action.from, to: action.to, ply: this.nonProgressPlies });
        if (list.length > 16) list.shift();
      }
    }
    const sig = this.computeSignature(boardAfter, reservesAfter, kingsAfter);
    this.stateSequence.push(sig);
    if (this.stateSequence.length > 80) this.stateSequence.shift();
    this.stateCounts.set(sig, (this.stateCounts.get(sig) || 0) + 1);
  },

  evaluateLoopPenalty(move, boardBefore, boardAfter, player, res1, res2, formsMillNow = false) {
    if (!move || move.type === 'drop' || move.type === 'jump' || move.type === 'remove_opponent' || formsMillNow) {
      return { penalty: 0, isForbiddenLoop: false, repCount: 0, oscCount: 0, breakthroughBonus: 0 };
    }
    const sigAfter = this.computeSignature(boardAfter, { 1: res1, 2: res2 }, GameState.kings);
    const repCount = this.stateCounts.get(sigAfter) || 0;

    const pList = this.playerMoves[player] || [];
    let oscCount = 0;
    for (let i = pList.length - 1; i >= 0; i--) {
      const pm = pList[i];
      const isSameEdge = (pm.from === move.to && pm.to === move.from) || (pm.from === move.from && pm.to === move.to);
      if (isSameEdge) {
        oscCount++;
      } else if (pm.to === move.from || pm.from === move.to) {
        if (pList.length - 1 - i <= 3) oscCount += 0.5;
      }
    }

    const lastMove = pList.length > 0 ? pList[pList.length - 1] : null;
    const isImmediateReversal = Boolean(lastMove && lastMove.from === move.to && lastMove.to === move.from);

    let penalty = 0;
    let isForbiddenLoop = false;

    if (isImmediateReversal) {
      penalty += 2200;
    }
    if (repCount === 1 || oscCount >= 1.5) {
      penalty += 4800;
    }
    if (repCount === 2 || oscCount >= 2.5) {
      penalty += 18000;
      isForbiddenLoop = true;
    }
    if (repCount >= 3 || oscCount >= 3.5) {
      penalty += 45000;
      isForbiddenLoop = true;
    }

    let breakthroughBonus = 0;
    if ((this.nonProgressPlies >= 4 || repCount >= 1 || isImmediateReversal) && lastMove && move.from !== lastMove.to) {
      breakthroughBonus += 950;
      const opp = player === 1 ? 2 : 1;
      if (Adjacency[move.to]) {
        for (const nb of Adjacency[move.to]) {
          if (boardAfter[nb] === opp) breakthroughBonus += 350;
        }
      }
    }

    return { penalty, isForbiddenLoop, repCount, oscCount, breakthroughBonus };
  }
};

