const MorrisLearner = {
  storageKey: 'katar_ai_brain_v4',
  table: new Map(),
  blunderKeys: new Set(),
  episode: [],
  loaded: false,
  gamesLearned: 0,
  mistakesCorrected: 0,
  archetypeStats: {},
  gameFamilyStats: {},
  lastArchetypeId: null,
  lastSymmetryIdx: -1,
  activeArchetypeId: 'iron_cross_bastion',
  activeSymmetryIdx: 0,
  recentFormationSignatures: [],
  tabooFormationSignatures: new Set(),
  humanNodeFreq: new Array(24).fill(0),
  humanPresetFreq: {},
  currentDropSequence: [],
  permCache: {},

  getGridPermutations(preset, R, C, tfList) {
    if (this.permCache[preset]) return this.permCache[preset];
    if (!Nodes || Nodes.length === 0) return null;
    const coordMap = new Map();
    for (let i = 0; i < Nodes.length; i++) {
      coordMap.set(`${Math.round(Nodes[i].r)},${Math.round(Nodes[i].c)}`, i);
    }
    const validPerms = [];
    for (const tf of tfList) {
      const p = new Array(Nodes.length);
      let ok = true;
      for (let i = 0; i < Nodes.length; i++) {
        const [nr, nc] = tf(Math.round(Nodes[i].r), Math.round(Nodes[i].c));
        const m = coordMap.get(`${nr},${nc}`);
        if (m === undefined) { ok = false; break; }
        p[i] = m;
      }
      if (ok) validPerms.push(p);
    }
    if (validPerms.length === 0) {
      validPerms.push(Array.from({ length: Nodes.length }, (_, i) => i));
    }
    this.permCache[preset] = validPerms;
    return validPerms;
  },

  load() {
    if (this.loaded) return;
    this.loaded = true;
    try {
      let raw = SafeStorage.getItem(this.storageKey);
      const isLegacy = !raw;
      if (!raw) raw = SafeStorage.getItem('katar_ai_brain_v3') || SafeStorage.getItem('katar_morris_brain_v2');
      if (!raw) return;
      const data = JSON.parse(raw);
      if (data && typeof data === 'object') {
        if (Array.isArray(data.entries)) {
          for (const [k, v] of data.entries) {
            if (typeof k === 'string' && typeof v === 'number') {
              const clamped = isLegacy ? Math.max(-2500, Math.min(2500, Math.round(v * 0.08))) : Math.max(-6000, Math.min(6000, v));
              if (Math.abs(clamped) >= 25) this.table.set(k, clamped);
            }
          }
        }
        if (!isLegacy && Array.isArray(data.blunderKeys)) {
          this.blunderKeys = new Set(data.blunderKeys.slice(-500));
        }
        this.gamesLearned = Number(data.gamesLearned) || 0;
        this.mistakesCorrected = Number(data.mistakesCorrected) || 0;
        this.archetypeStats = data.archetypeStats || {};
        this.gameFamilyStats = data.gameFamilyStats || {};
        this.lastArchetypeId = data.lastArchetypeId || null;
        this.lastSymmetryIdx = typeof data.lastSymmetryIdx === 'number' ? data.lastSymmetryIdx : -1;
        if (Array.isArray(data.recentFormationSignatures)) {
          this.recentFormationSignatures = data.recentFormationSignatures.slice(-12);
        }
        if (Array.isArray(data.tabooFormationSignatures)) {
          this.tabooFormationSignatures = new Set(data.tabooFormationSignatures.slice(-40));
        }
        if (Array.isArray(data.humanNodeFreq) && data.humanNodeFreq.length === 24) {
          this.humanNodeFreq = data.humanNodeFreq.map((n) => Number(n) || 0);
        }
        if (data.humanPresetFreq && typeof data.humanPresetFreq === 'object') {
          this.humanPresetFreq = data.humanPresetFreq;
        }
        if (isLegacy) this.save();
      }
    } catch (e) {}
  },

  save() {
    try {
      if (this.table.size > 9000) {
        const sorted = Array.from(this.table.entries())
          .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
          .slice(0, 6000);
        this.table = new Map(sorted);
      }
      const payload = {
        entries: Array.from(this.table.entries()),
        blunderKeys: Array.from(this.blunderKeys).slice(-500),
        gamesLearned: this.gamesLearned,
        mistakesCorrected: this.mistakesCorrected,
        archetypeStats: this.archetypeStats,
        gameFamilyStats: this.gameFamilyStats,
        lastArchetypeId: this.lastArchetypeId,
        lastSymmetryIdx: this.lastSymmetryIdx,
        recentFormationSignatures: this.recentFormationSignatures.slice(-12),
        tabooFormationSignatures: Array.from(this.tabooFormationSignatures).slice(-40),
        humanNodeFreq: this.humanNodeFreq,
        humanPresetFreq: this.humanPresetFreq
      };
      SafeStorage.setItem(this.storageKey, JSON.stringify(payload));
    } catch (e) {}
  },

  resetBrain() {
    this.table.clear();
    this.blunderKeys.clear();
    this.episode = [];
    this.currentDropSequence = [];
    this.gamesLearned = 0;
    this.mistakesCorrected = 0;
    this.archetypeStats = {};
    this.gameFamilyStats = {};
    this.lastArchetypeId = null;
    this.lastSymmetryIdx = -1;
    this.tabooFormationSignatures.clear();
    this.recentFormationSignatures = [];
    this.humanNodeFreq = new Array(24).fill(0);
    this.humanPresetFreq = {};
    SafeStorage.removeItem(this.storageKey);
    SafeStorage.removeItem('katar_ai_brain_v3');
    SafeStorage.removeItem('katar_morris_brain_v2');
    this.save();
  },

  getIntelligenceLevel() {
    const pts = (this.gamesLearned * 2) + (this.mistakesCorrected * 3);
    if (pts >= 100) return { level: 5, title: 'Supreme Overlord AI', depthBonus: 3, bonusFactor: 1.0 };
    if (pts >= 45) return { level: 4, title: 'Apex Grandmaster', depthBonus: 2, bonusFactor: 0.9 };
    if (pts >= 20) return { level: 3, title: 'Strategic Master', depthBonus: 2, bonusFactor: 0.8 };
    if (pts >= 8) return { level: 2, title: 'Tactical Veteran', depthBonus: 1, bonusFactor: 0.7 };
    return { level: 1, title: 'Grandmaster Khan', depthBonus: 1, bonusFactor: 0.6 };
  },

  onMatchStart() {
    this.load();
    this.episode = [];
    this.currentDropSequence = [];
    MorrisKillerMoves = [];
    MorrisHistoryTable = { 1: new Int32Array(600), 2: new Int32Array(600) };
    const candidates = [];
    for (const arch of GRANDMASTER_MORRIS_ARCHETYPES) {
      const st = this.archetypeStats[arch.id] || { wins: 0, losses: 0, draws: 0, plays: 0 };
      const winRate = (st.wins + 1.5) / (st.plays + 2.2);
      const exploreBonus = Math.sqrt(Math.log((this.gamesLearned || 1) + 2) / (st.plays + 1)) * 0.38;
      const repeatPenalty = (arch.id === this.lastArchetypeId) ? -1.2 : 0;
      const lossStreakPenalty = (st.lastOutcome === 'loss') ? -0.95 : 0;
      candidates.push({
        arch,
        score: winRate + exploreBonus + repeatPenalty + lossStreakPenalty + (Math.random() * 0.15)
      });
    }
    candidates.sort((a, b) => b.score - a.score);
    const chosenArch = candidates[0].arch;

    const symOrder = [0, 1, 2, 3, 4, 5, 6, 7].sort(() => Math.random() - 0.5);
    let chosenSym = symOrder[0];
    for (const s of symOrder) {
      if (s === this.lastSymmetryIdx) continue;
      const sig = `${chosenArch.id}@${s}`;
      if (!this.tabooFormationSignatures.has(sig) && !this.recentFormationSignatures.slice(-3).includes(sig)) {
        chosenSym = s;
        break;
      }
    }

    this.activeArchetypeId = chosenArch.id;
    this.activeSymmetryIdx = chosenSym;
    this.lastArchetypeId = chosenArch.id;
    this.lastSymmetryIdx = chosenSym;
    this.recentFormationSignatures.push(`${chosenArch.id}@${chosenSym}`);
    if (this.recentFormationSignatures.length > 12) this.recentFormationSignatures.shift();
    this.save();
  },

  getActiveBlueprintNodes() {
    this.load();
    if (Nodes.length === 9) {
      return [4, 0, 2, 6, 8, 1, 3, 5, 7].map((nid) => MorrisSymmetry.transformNode(nid, this.activeSymmetryIdx || 0));
    }
    if (Nodes.length === 16) {
      return [1, 3, 5, 7, 9, 11, 13, 15, 0, 4, 8, 12].map((nid) => MorrisSymmetry.transformNode(nid, this.activeSymmetryIdx || 0));
    }
    const arch = GRANDMASTER_MORRIS_ARCHETYPES.find((a) => a.id === this.activeArchetypeId) || GRANDMASTER_MORRIS_ARCHETYPES[0];
    const sym = this.activeSymmetryIdx || 0;
    return arch.nodes.map((nid) => MorrisSymmetry.transformNode(nid, sym));
  },

  recordHumanAction(board, action, humanP) {
    this.load();
    if (!action) return;
    if (action.to >= 0) {
      if (GameState.gameFamily === 'morris' && action.to < 24) {
        this.humanNodeFreq[action.to] = (this.humanNodeFreq[action.to] || 0) + 1;
      }
      const preset = GameState.gridPreset || 'custom';
      if (!this.humanPresetFreq[preset]) this.humanPresetFreq[preset] = {};
      this.humanPresetFreq[preset][action.to] = (this.humanPresetFreq[preset][action.to] || 0) + 1;
    }
    // Positive imitation learning: remember strong human moves that form mills or double threats
    if (GameState.gameFamily === 'morris' && (action.type === 'drop' || action.type === 'step')) {
      const opp = humanP === 1 ? 2 : 1;
      const resH = (GameState.reserves && GameState.reserves[humanP]) || 0;
      const resA = (GameState.reserves && GameState.reserves[opp]) || 0;
      const sim = [...board];
      if (action.type === 'step' && action.from >= 0) sim[action.from] = 0;
      sim[action.to] = humanP;
      const forbidM = (GameState.morrisDropOrder === 'all_at_once' || GameState.morrisDropMillRule === 'forbid_mill');
      const formed = !(action.type === 'drop' && forbidM) && fastCountMillsAtNode(action.to, humanP, sim) > 0;
      if (formed) {
        const { fullKey } = this.makeStateKey(board, action, humanP, resH, resA);
        this.adjustWeight(fullKey, 420);
      }
    }
  },

  makeStateKey(board, action, aiP, resAi = 0, resHuman = 0) {
    if (GameState.gameFamily === 'morris') {
      const canon = MorrisSymmetry.canonicalizeStateAndAction(board, action, aiP);
      const ruleTag = `${GameState.gridPreset}:${GameState.morrisDiagonals ? 1 : 0}:${GameState.morrisDropOrder === 'all_at_once' ? 'A' : (GameState.morrisDropMillRule === 'forbid_mill' ? 'F' : 'S')}:${GameState.morrisMillRemovalRule === 'any' ? 'K' : 'P'}:${GameState.morrisFlyingRule === 'enabled' ? 'Y' : 'N'}`;
      const phaseTag = (resAi > 0 || resHuman > 0) ? `D${resAi}_${resHuman}` : 'M';
      return {
        fullKey: `${ruleTag}:${phaseTag}:${canon.stateKey}|${canon.actionKey}`,
        stateOnlyKey: `${ruleTag}:${phaseTag}:${canon.stateKey}`
      };
    }

    const R = GameState.rows || 1;
    const C = GameState.cols || 1;
    const isSquare = (R === C);
    const tfList = [
      (r, c) => [r, c],
      (r, c) => [r, C - 1 - c],
      (r, c) => [R - 1 - r, c],
      (r, c) => [R - 1 - r, C - 1 - c]
    ];
    if (isSquare) {
      tfList.push(
        (r, c) => [c, r],
        (r, c) => [c, R - 1 - r],
        (r, c) => [C - 1 - c, r],
        (r, c) => [C - 1 - c, R - 1 - r]
      );
    }
    const perms = this.getGridPermutations(GameState.gridPreset, R, C, tfList) || [[...Array(board.length).keys()]];

    let bestBoardStr = null;
    let bestActStr = '';
    const hasKings = Boolean(GameState.kings && GameState.kings.length === board.length);

    for (let s = 0; s < perms.length; s++) {
      const perm = perms[s];
      const inv = new Array(board.length);
      for (let i = 0; i < board.length; i++) inv[perm[i]] = i;
      let bStr = '';
      for (let j = 0; j < board.length; j++) {
        const v = board[inv[j]];
        if (v === 0) bStr += '0';
        else if (v === aiP) bStr += (hasKings && GameState.kings[inv[j]] ? 'K' : 'A');
        else bStr += (hasKings && GameState.kings[inv[j]] ? 'k' : 'H');
      }
      let aStr = '';
      if (action) {
        if (action.type === 'drop') aStr = `d:${perm[action.to]}`;
        else if (action.type === 'step') aStr = `s:${perm[action.from]}>${perm[action.to]}`;
        else if (action.type === 'jump') aStr = `j:${perm[action.from]}>${perm[action.to]}`;
        else if (action.type === 'remove_opponent') aStr = `r:${perm[action.capturedId]}`;
      }
      if (bestBoardStr === null || bStr < bestBoardStr || (bStr === bestBoardStr && aStr < bestActStr)) {
        bestBoardStr = bStr;
        bestActStr = aStr;
      }
    }

    const famTag = GameState.gameFamily || 'g';
    const presetTag = GameState.gridPreset || 'p';
    const phaseTag = (resAi > 0 || resHuman > 0) ? `D${resAi}_${resHuman}` : 'M';
    return {
      fullKey: `${famTag}:${presetTag}:${phaseTag}:${bestBoardStr}|${bestActStr}`,
      stateOnlyKey: `${famTag}:${presetTag}:${phaseTag}:${bestBoardStr}`
    };
  },

  getBonus(board, action, aiP, resAi = 0, resHuman = 0) {
    this.load();
    const { fullKey } = this.makeStateKey(board, action, aiP, resAi, resHuman);
    if (this.blunderKeys.has(fullKey)) return -4500;
    const w = this.table.get(fullKey) || 0;
    return Math.max(-2200, Math.min(2200, w));
  },

  isBlunder(board, action, aiP, resAi = 0, resHuman = 0) {
    this.load();
    const { fullKey } = this.makeStateKey(board, action, aiP, resAi, resHuman);
    if (this.blunderKeys.has(fullKey)) return true;
    const w = this.table.get(fullKey) || 0;
    return w <= -2800;
  },

  getHardestBonus(board, action, aiP, resAi = 0, resHuman = 0) {
    this.load();
    const { fullKey } = this.makeStateKey(board, action, aiP, resAi, resHuman);
    if (this.blunderKeys.has(fullKey)) return -6500;
    const w = this.table.get(fullKey) || 0;
    if (w <= -2800) return -5500;
    const lvl = this.getIntelligenceLevel();
    return Math.max(-2800, Math.min(2800, Math.round(w * lvl.bonusFactor)));
  },

  recordStep(board, action, aiP, resAi = 0, resHuman = 0) {
    this.load();
    if (!action) return;
    if (action.type === 'drop') {
      this.currentDropSequence.push(action.to);
    }
    const { fullKey } = this.makeStateKey(board, action, aiP, resAi, resHuman);
    this.episode.push({ fullKey, action, board: [...board], aiP, resAi, resHuman });
    if (this.episode.length > 90) this.episode.shift();
  },

  adjustWeight(fullKey, delta) {
    const prev = this.table.get(fullKey) || 0;
    const next = Math.max(-6000, Math.min(6000, Math.round(prev * 0.85 + delta)));
    if (Math.abs(next) < 25) this.table.delete(fullKey);
    else this.table.set(fullKey, next);
  },

  onHumanCapturedAiBead(count = 1) {
    this.load();
    this.mistakesCorrected += count;
    if (this.episode.length === 0) return;
    const lastIdx = this.episode.length - 1;
    const lastMove = this.episode[lastIdx];
    this.blunderKeys.add(lastMove.fullKey);
    this.adjustWeight(lastMove.fullKey, -1600 * count);
    if (lastIdx >= 1) {
      this.adjustWeight(this.episode[lastIdx - 1].fullKey, -850 * count);
    }
    if (lastIdx >= 2) {
      this.adjustWeight(this.episode[lastIdx - 2].fullKey, -420 * count);
    }
    this.save();
  },

  onMatchEnd(winner) {
    if (!GameState.vsAI) {
      this.episode = [];
      return;
    }
    this.load();
    const aiP = (GameState.aiVsAi && (winner === 1 || winner === 2)) ? winner : (GameState.aiPlayerRole || 2);
    this.gamesLearned++;

    const fam = GameState.gameFamily || 'general';
    if (!this.gameFamilyStats[fam]) this.gameFamilyStats[fam] = { wins: 0, losses: 0, draws: 0, plays: 0 };
    this.gameFamilyStats[fam].plays++;

    const archId = this.activeArchetypeId || 'iron_cross_bastion';
    const st = this.archetypeStats[archId] || { wins: 0, losses: 0, draws: 0, plays: 0, lastOutcome: 'none' };
    st.plays++;

    if (winner === aiP) {
      st.wins++;
      st.lastOutcome = 'win';
      this.gameFamilyStats[fam].wins++;
      if (this.episode.length > 0) {
        let discountWin = 1.0;
        let discountLoss = 1.0;
        for (let i = this.episode.length - 1; i >= 0; i--) {
          const ep = this.episode[i];
          if (!ep.aiP || ep.aiP === winner) {
            const stepDelta = Math.round(900 * discountWin);
            if (Math.abs(stepDelta) >= 25) {
              this.adjustWeight(ep.fullKey, stepDelta);
            }
            discountWin *= 0.9;
          } else if (GameState.aiVsAi) {
            const penDelta = Math.round(-1100 * discountLoss);
            if (Math.abs(penDelta) >= 25) {
              this.adjustWeight(ep.fullKey, penDelta);
            }
            discountLoss *= 0.88;
          }
        }
      }
    } else if (winner === 0 || winner === null) {
      st.draws++;
      st.lastOutcome = 'draw';
      this.gameFamilyStats[fam].draws++;
      if (this.episode.length > 0) {
        for (let i = this.episode.length - 1; i >= 0; i--) {
          this.adjustWeight(this.episode[i].fullKey, 150);
        }
      }
    } else {
      st.losses++;
      st.lastOutcome = 'loss';
      this.gameFamilyStats[fam].losses++;
      this.mistakesCorrected++;
      this.tabooFormationSignatures.add(`${archId}@${this.activeSymmetryIdx}`);
      if (this.currentDropSequence.length > 0) {
        const sortedDrops = [...this.currentDropSequence].sort((a, b) => a - b).join(',');
        this.tabooFormationSignatures.add(`DROP:${sortedDrops}`);
      }
      if (this.episode.length > 0) {
        const lastIdx = this.episode.length - 1;
        this.blunderKeys.add(this.episode[lastIdx].fullKey);
        this.adjustWeight(this.episode[lastIdx].fullKey, -2400);
        if (lastIdx >= 1) {
          this.blunderKeys.add(this.episode[lastIdx - 1].fullKey);
          this.adjustWeight(this.episode[lastIdx - 1].fullKey, -1600);
        }
        if (lastIdx >= 2) {
          this.blunderKeys.add(this.episode[lastIdx - 2].fullKey);
          this.adjustWeight(this.episode[lastIdx - 2].fullKey, -1000);
        }
        let discount = 0.86;
        for (let i = lastIdx - 3; i >= 0; i--) {
          const stepDelta = Math.round(-750 * discount);
          if (Math.abs(stepDelta) >= 25) {
            this.adjustWeight(epSafeKey(this.episode[i]), stepDelta);
          }
          discount *= 0.86;
        }
      }
    }
    this.archetypeStats[archId] = st;
    this.episode = [];
    this.currentDropSequence = [];
    this.save();
    if (typeof PuterAIManager !== 'undefined') {
      PuterAIManager.syncModalUI();
    }
  }
};

function epSafeKey(ep) {
  return ep && ep.fullKey ? ep.fullKey : '';
}

function getMorrisNodeWeight(nodeId) {
  ensureMorrisTopologyCache();
  if (nodeId >= 0 && nodeId < NodeDegreeWeights.length) {
    return NodeDegreeWeights[nodeId];
  }
  const deg = Adjacency[nodeId] ? Adjacency[nodeId].size : 2;
  return deg >= 4 ? 52 : (deg === 3 ? 34 : 18);
}

function hasReadySliderForMill(emptyNodeId, line, player, board) {
  if (!Adjacency[emptyNodeId]) return false;
  for (const nb of Adjacency[emptyNodeId]) {
    if (nb !== line[0] && nb !== line[1] && nb !== line[2] && board[nb] === player) return true;
  }
  return false;
}

function countReadySlidersForMill(emptyNodeId, line, player, board) {
  if (!Adjacency[emptyNodeId]) return 0;
  let count = 0;
  for (const nb of Adjacency[emptyNodeId]) {
    if (nb !== line[0] && nb !== line[1] && nb !== line[2] && board[nb] === player) count++;
  }
  return count;
}

function canPlayerFlyOnBoard(player, board, reserves) {
  if (GameState.morrisFlyingRule !== 'enabled') return false;
  if (GameState.gridPreset === 'three_morris' || GameState.gridPreset === 'six_morris') return false;
  if (reserves && reserves[player] > 0) return false;
  return countPlayerTotalPieces(player, board, reserves) === 3;
}

function canPlayerCloseMillAt(emptyNodeId, line, player, board, reserves) {
  if (reserves && reserves[player] > 0) {
    const forbidLandingMill = (GameState.morrisDropOrder === 'all_at_once' || GameState.morrisDropMillRule === 'forbid_mill');
    if (!forbidLandingMill) return true;
    return hasReadySliderForMill(emptyNodeId, line, player, board);
  }
  if (canPlayerFlyOnBoard(player, board, reserves)) return true;
  return hasReadySliderForMill(emptyNodeId, line, player, board);
}

// Count how many open 2-in-a-row threats dropping at `nodeId` creates for `player`
function analyzeDropForkPotential(nodeId, player, board, reserves) {
  ensureMorrisTopologyCache();
  const pairs = NodeMillPairs[nodeId];
  if (!pairs) return { millCount: 0, openTwoTargets: [], loadedTargets: [] };
  const forbidLandingMill = (GameState.morrisDropOrder === 'all_at_once' || GameState.morrisDropMillRule === 'forbid_mill');
  let millCount = 0;
  const openTwoTargets = [];
  const loadedTargets = [];

  for (let i = 0; i < pairs.length; i++) {
    const [o1, o2, lineIdx] = pairs[i];
    const v1 = board[o1];
    const v2 = board[o2];
    if (v1 === player && v2 === player) {
      millCount++;
    } else if ((v1 === player && v2 === 0) || (v2 === player && v1 === 0)) {
      const empId = v1 === 0 ? o1 : o2;
      openTwoTargets.push(empId);
      const line = MillLines[lineIdx];
      if (hasReadySliderForMill(empId, line, player, board)) {
        loadedTargets.push(empId);
      }
    }
  }

  // Also check if dropping at `nodeId` acts as the outside SLIDER that arms an existing 2-in-a-row!
  if (Adjacency[nodeId]) {
    for (const nb of Adjacency[nodeId]) {
      if (board[nb] !== 0) continue;
      const nbPairs = NodeMillPairs[nb];
      if (!nbPairs) continue;
      for (let j = 0; j < nbPairs.length; j++) {
        const [p1, p2] = nbPairs[j];
        if (p1 === nodeId || p2 === nodeId) continue;
        if (board[p1] === player && board[p2] === player) {
          if (!loadedTargets.includes(nb)) loadedTargets.push(nb);
        }
      }
    }
  }

  return {
    millCount: forbidLandingMill ? 0 : millCount,
    rawMillCount: millCount,
    openTwoTargets,
    loadedTargets
  };
}

function scoreMorrisRemovalTarget(cid, board, aiP, humanP, res1 = GameState.reserves[1], res2 = GameState.reserves[2]) {
  ensureMorrisTopologyCache();
  const res = { 1: res1, 2: res2 };
  let score = getMorrisNodeWeight(cid) * 30;

  const simB = [...board];
  simB[cid] = 0;
  const hmRemaining = countPlayerTotalPieces(humanP, simB, res);
  if (hmRemaining <= 2) return 400000;
  if (res[humanP] === 0) {
    const oppActs = getAllLegalActionsForPlayer(humanP, simB, res);
    if (oppActs.total === 0) return 380000;
  }

  const oppWillFlyAfterRemoval = canPlayerFlyOnBoard(humanP, simB, res);
  const pairs = NodeMillPairs[cid] || [];
  let inOpenTwo = 0;
  let inOneWithTwoEmpty = 0;

  for (let i = 0; i < pairs.length; i++) {
    const [o1, o2, lineIdx] = pairs[i];
    const line = MillLines[lineIdx];
    let oppC = 1;
    let aiC = 0;
    let empId = -1;
    if (board[o1] === humanP) oppC++;
    else if (board[o1] === aiP) aiC++;
    else empId = o1;

    if (board[o2] === humanP) oppC++;
    else if (board[o2] === aiP) aiC++;
    else empId = o2;

    if (oppC === 2 && empId !== -1 && aiC === 0) {
      inOpenTwo++;
      // Check both current board AND post-removal board (in case removal unlocks flying!)
      if (canPlayerCloseMillAt(empId, line, humanP, board, res) || canPlayerCloseMillAt(empId, line, humanP, simB, res)) {
        score += 85000;
      } else {
        score += 28000;
      }
    } else if (oppC === 1 && aiC === 0) {
      inOneWithTwoEmpty++;
    }

    // Removing `cid` unblocks an AI 2-in-a-row on this exact line!
    if (aiC === 2 && oppC === 1) {
      if (canPlayerCloseMillAt(cid, line, aiP, simB, res)) {
        score += 72000;
      } else {
        score += 26000;
      }
    } else if (aiC === 1 && oppC === 1 && empId !== -1) {
      // Opens a full mill line for AI
      score += 6500;
    }
  }

  // CRITICAL FLYING RULE AWARENESS: If removing `cid` reduces opponent to 3 beads in Flying Mode,
  // check if the OTHER 3 remaining opponent beads on `simB` form any 2-in-a-row that can now fly-close!
  if (oppWillFlyAfterRemoval) {
    let survivingTwoInRows = 0;
    for (let lIdx = 0; lIdx < MillLines.length; lIdx++) {
      const [a, b, c] = MillLines[lIdx];
      let hC = 0, eC = 0;
      if (simB[a] === humanP) hC++; else if (simB[a] === 0) eC++;
      if (simB[b] === humanP) hC++; else if (simB[b] === 0) eC++;
      if (simB[c] === humanP) hC++; else if (simB[c] === 0) eC++;
      if (hC === 2 && eC === 1) survivingTwoInRows++;
    }
    if (survivingTwoInRows > 0) {
      score -= survivingTwoInRows * 90000;
    } else {
      score += 35000;
    }
  }

  if (inOpenTwo >= 2) score += 65000;
  if (inOneWithTwoEmpty >= 2) score += 9500; // Break opponent L-fork pivot

  // Check if `cid` is the outside slider about to slide into an empty node `nb` to complete a mill
  for (const nb of Adjacency[cid]) {
    if (board[nb] === 0) {
      const nbPairs = NodeMillPairs[nb] || [];
      for (let j = 0; j < nbPairs.length; j++) {
        const [p1, p2, lIdx] = nbPairs[j];
        if (p1 === cid || p2 === cid) continue;
        if (board[p1] === humanP && board[p2] === humanP) {
          const otherSliders = countReadySlidersForMill(nb, MillLines[lIdx], humanP, simB);
          score += otherSliders === 0 ? 78000 : 28000;
        }
      }
    }
  }

  // In 'any' mode (or when all opponent beads are in mills), breaking an active/running mill or see-saw
  if (fastCountMillsAtNode(cid, humanP, board) > 0) {
    let canReopenSafely = false;
    let partOfSeeSaw = false;
    for (let i = 0; i < pairs.length; i++) {
      const [o1, o2, lIdx] = pairs[i];
      if (board[o1] !== humanP || board[o2] !== humanP) continue;
      const m1 = MillLines[lIdx];
      for (const nid of m1) {
        for (const nb of Adjacency[nid]) {
          if (!m1.includes(nb) && board[nb] === 0) {
            canReopenSafely = true;
            if (fastWouldCompleteMill(nb, humanP, board) > 0) {
              partOfSeeSaw = true;
            }
          }
        }
      }
    }
    if (partOfSeeSaw) score += 92000;
    else if (canReopenSafely) score += 44000;
    else score += 18000;
  }

  let oppEmptyNeighbors = 0;
  let friendlyTrappedFreed = 0;
  for (const nb of Adjacency[cid]) {
    if (board[nb] === 0) oppEmptyNeighbors++;
    else if (board[nb] === aiP) {
      let libBefore = 0;
      for (const anb of Adjacency[nb]) if (board[anb] === 0) libBefore++;
      if (libBefore === 0) friendlyTrappedFreed++;
    }
  }
  score += oppEmptyNeighbors * 350 + friendlyTrappedFreed * 8500;
  return score;
}

function pickBestMorrisRemoval(board, aiP, humanP, res1 = GameState.reserves[1], res2 = GameState.reserves[2]) {
  const candidates = getRemovableOpponentNodes(humanP, board);
  if (candidates.length === 0) return -1;
  let bestId = candidates[0];
  let bestScore = -Infinity;
  for (const cid of candidates) {
    const sc = scoreMorrisRemovalTarget(cid, board, aiP, humanP, res1, res2);
    if (sc > bestScore) {
      bestScore = sc;
      bestId = cid;
    }
  }
  return bestId;
}

function getTopMorrisRemovals(board, aiP, humanP, res1, res2, maxCount = 3) {
  const candidates = getRemovableOpponentNodes(humanP, board);
  if (candidates.length <= 1) return candidates;
  const scored = candidates.map((cid) => ({
    cid,
    sc: scoreMorrisRemovalTarget(cid, board, aiP, humanP, res1, res2)
  }));
  scored.sort((a, b) => b.sc - a.sc);
  return scored.slice(0, maxCount).map((x) => x.cid);
}

// Grandmaster evaluation for "Lay All Beads First" (both 1st-Placer and 2nd-Placer)
function evaluateAllAtOnceBoard(board, aiP, humanP, resAi, resHuman) {
  ensureMorrisTopologyCache();
  const blueprint = MorrisLearner.getActiveBlueprintNodes();
  const humanFreq = MorrisLearner.humanNodeFreq || [];
  const totalLines = MillLines.length;

  // CASE A: AI is laying all beads FIRST (resHuman > 0, human hasn't placed yet)
  if (resHuman > 0) {
    let score = 0;
    let linesCovered = 0;
    let linesWithTwo = 0;
    const readyTargets = new Set();
    const multiSliderTargets = new Set();
    const cageTrapTargets = new Set();
    const openTwoTargets = new Set();
    const targetShareCount = new Map();
    const frontierSet = new Set();

    const placedNodes = [];
    for (let i = 0; i < Nodes.length; i++) {
      if (board[i] !== aiP) continue;
      placedNodes.push(i);
      score += getMorrisNodeWeight(i) * 320;

      const bpIdx = blueprint.indexOf(i);
      if (bpIdx !== -1 && bpIdx < GameState.piecesPerPlayer) {
        score += 22000 + (12 - bpIdx) * 1600;
      }

      if (i < humanFreq.length && humanFreq[i] > 0) {
        score += Math.min(4500, humanFreq[i] * 650);
      }

      let empNb = 0;
      let friendlyNb = 0;
      for (const nb of Adjacency[i]) {
        if (board[nb] === 0) {
          empNb++;
          frontierSet.add(nb);
        } else if (board[nb] === aiP) {
          friendlyNb++;
        }
      }
      if (empNb === 0) score -= 85000;
      else if (empNb === 1) score -= 26000;
      else score += empNb * 2400;

      const deg = Adjacency[i] ? Adjacency[i].size : 2;
      if (deg === 2 && friendlyNb >= 2) {
        score -= 22000;
      }
    }

    if (resAi === 0 && placedNodes.length >= 6) {
      const dropSig = `DROP:${placedNodes.slice().sort((a, b) => a - b).join(',')}`;
      if (MorrisLearner.tabooFormationSignatures.has(dropSig)) {
        score -= 220000;
      }
    }

    score += frontierSet.size * 4200;

    for (const line of MillLines) {
      let aC = 0, hC = 0, empNode = -1;
      for (const id of line) {
        if (board[id] === aiP) aC++;
        else if (board[id] === humanP) hC++;
        else empNode = id;
      }
      if (aC >= 1 && hC === 0) {
        linesCovered++;
      }
      if (aC === 2 && hC === 0 && empNode !== -1) {
        linesWithTwo++;
        openTwoTargets.add(empNode);
        targetShareCount.set(empNode, (targetShareCount.get(empNode) || 0) + 1);
        const sliders = countReadySlidersForMill(empNode, line, aiP, board);
        if (sliders >= 1) {
          readyTargets.add(empNode);
          if (sliders >= 2) multiSliderTargets.add(empNode);
          let emptyNeighborsOfTarget = 0;
          for (const nb of Adjacency[empNode]) {
            if (board[nb] === 0) emptyNeighborsOfTarget++;
          }
          if (emptyNeighborsOfTarget === 0) {
            cageTrapTargets.add(empNode);
          }
        }
      }
    }

    if (Nodes.length === 24 && resAi <= 3) {
      let outerC = 0, midC = 0, innerC = 0;
      const outerSet = [0, 1, 2, 9, 14, 21, 22, 23];
      const midSet = [3, 4, 5, 10, 13, 18, 19, 20];
      const innerSet = [6, 7, 8, 11, 12, 15, 16, 17];
      for (const id of outerSet) if (board[id] === aiP) outerC++;
      for (const id of midSet) if (board[id] === aiP) midC++;
      for (const id of innerSet) if (board[id] === aiP) innerC++;
      if (resAi === 0) {
        if (outerC < 2) score -= 140000;
        if (midC < 2) score -= 140000;
        if (innerC < 2) score -= 140000;
      } else {
        if (outerC === 0) score -= 45000;
        if (midC === 0) score -= 45000;
        if (innerC === 0) score -= 45000;
      }
    }

    score += linesCovered * 26000;
    if (linesCovered >= totalLines - 2) score += 65000;
    if (linesCovered >= totalLines - 1) score += 95000;
    if (linesCovered >= totalLines) score += 175000;

    score += openTwoTargets.size * 10000;
    score += readyTargets.size * 38000;
    score += multiSliderTargets.size * 25000;
    score += cageTrapTargets.size * 62000;

    for (const [, count] of targetShareCount) {
      if (count > 1) score -= (count - 1) * 18000;
    }

    // When AI finishes placing its Nth bead first, simulate Human's best N counter-drops,
    // and then evaluate with `turnPlayer = aiP` because AI moves FIRST in the Slide Phase!
    if (resAi === 0) {
      const simBoard = [...board];
      let hmLeft = Math.min(resHuman, GameState.piecesPerPlayer);
      while (hmLeft > 0) {
        let bestHNode = -1;
        let bestHVal = -Infinity;
        for (let i = 0; i < Nodes.length; i++) {
          if (simBoard[i] !== 0) continue;
          simBoard[i] = humanP;
          if (fastCountMillsAtNode(i, humanP, simBoard) > 0) {
            simBoard[i] = 0;
            continue;
          }
          let hVal = getMorrisNodeWeight(i) * 40;
          if (readyTargets.has(i)) hVal += 55000;
          else if (openTwoTargets.has(i)) hVal += 22000;
          for (const line of MillLines) {
            if (!line.includes(i)) continue;
            let hC = 0, aC = 0, emp = -1;
            for (const id of line) {
              if (simBoard[id] === humanP) hC++;
              else if (simBoard[id] === aiP) aC++;
              else emp = id;
            }
            if (hC === 2 && aC === 0 && emp !== -1) {
              hVal += hasReadySliderForMill(emp, line, humanP, simBoard) ? 34000 : 11000;
            }
          }
          // Human also tries to block AI liberties
          for (const nb of Adjacency[i]) {
            if (simBoard[nb] === aiP) hVal += 2500;
          }
          simBoard[i] = 0;
          if (hVal > bestHVal) {
            bestHVal = hVal;
            bestHNode = i;
          }
        }
        if (bestHNode === -1) break;
        simBoard[bestHNode] = humanP;
        hmLeft--;
      }
      const postEval = evaluateMorrisBoardState(simBoard, 0, 0, aiP, aiP, humanP);
      score += postEval * 3.2;
    }

    return score;
  }

  // CASE B: Human already placed all N beads first (resHuman === 0), now AI places its N beads!
  // Note: Human's beads are 100% frozen until AI finishes all N drops, and then Human slides first
  // (UNLESS Human has 0 legal moves, in which case AI wins immediately on its final drop!).
  let score = evaluateMorrisBoardState(board, 0, 0, humanP, aiP, humanP) * 4.5;
  const hmReadyTargets = new Set();
  const hmTwoStepTargets = new Set();
  const hmOpenTwoWithoutSlider = new Set();
  const aiReadyTargets = new Set();
  const aiUncontestedTargets = new Set();

  for (const line of MillLines) {
    let a = 0, h = 0, emp = -1;
    for (const id of line) {
      if (board[id] === aiP) a++;
      else if (board[id] === humanP) h++;
      else emp = id;
    }
    if (h === 2 && a === 0 && emp !== -1) {
      if (hasReadySliderForMill(emp, line, humanP, board)) {
        hmReadyTargets.add(emp);
      } else {
        hmOpenTwoWithoutSlider.add(emp);
        // Check if a human bead is 2 steps away from `emp`
        for (const nb of Adjacency[emp]) {
          if (board[nb] === 0 && !line.includes(nb)) {
            for (const nb2 of Adjacency[nb]) {
              if (!line.includes(nb2) && board[nb2] === humanP) {
                hmTwoStepTargets.add(emp);
                break;
              }
            }
          }
        }
      }
    } else if (a === 2 && h === 0 && emp !== -1) {
      if (hasReadySliderForMill(emp, line, aiP, board)) {
        aiReadyTargets.add(emp);
        let oppCanSlideIntoEmp = false;
        for (const nb of Adjacency[emp]) {
          if (board[nb] === humanP) {
            oppCanSlideIntoEmp = true;
            break;
          }
        }
        if (!oppCanSlideIntoEmp) aiUncontestedTargets.add(emp);
      }
    }
  }

  score -= hmReadyTargets.size * 260000;
  score -= hmTwoStepTargets.size * 48000;
  score -= hmOpenTwoWithoutSlider.size * 22000;
  score += aiReadyTargets.size * 46000;
  score += aiUncontestedTargets.size * 92000;
  if (aiUncontestedTargets.size >= 1 && hmReadyTargets.size === 0) score += 115000;
  if (aiUncontestedTargets.size >= 2) score += 140000;

  // Calculate Human's Liberty Frontier for Encirclement / Immobilization Win!
  const hmLibertyNodes = new Set();
  let hmMob = 0;
  let hmTrapped = 0;
  for (let i = 0; i < Nodes.length; i++) {
    if (board[i] === humanP) {
      let lib = 0;
      for (const nb of Adjacency[i]) {
        if (board[nb] === 0) {
          lib++;
          hmLibertyNodes.add(nb);
        }
      }
      hmMob += lib;
      if (lib === 0) hmTrapped++;
    }
  }
  if (hmMob === 0) return 1500000; // Instant immobilization victory!
  if (hmLibertyNodes.size <= resAi) {
    // AI has enough beads left in hand to plug EVERY remaining human liberty and win immediately!
    score += (resAi - hmLibertyNodes.size + 1) * 180000;
  }
  score += hmTrapped * 28000;
  score -= hmMob * 2400;
  score -= hmLibertyNodes.size * 4200;

  return score;
}

// Grandmaster Single-Drop Evaluator (aware of allow_mill, forbid_mill, all_at_once, 9/12/6/3 variants)
function scoreMorrisPlacement(nodeId, board, aiP, humanP, isAllAtOnce, resAi, resHuman) {
  ensureMorrisTopologyCache();
  const landingMillForbidden = (isAllAtOnce || GameState.morrisDropMillRule === 'forbid_mill');
  const sim = [...board];
  sim[nodeId] = aiP;

  if (isAllAtOnce) {
    return evaluateAllAtOnceBoard(sim, aiP, humanP, Math.max(0, resAi - 1), resHuman);
  }

  const myForkInfo = analyzeDropForkPotential(nodeId, aiP, board, GameState.reserves);
  const oppForkInfo = analyzeDropForkPotential(nodeId, humanP, board, GameState.reserves);

  if (!landingMillForbidden) {
    const myMills = myForkInfo.rawMillCount;
    const oppMills = oppForkInfo.rawMillCount;
    if (myMills > 0) {
      return 420000 + myMills * 55000 + oppMills * 35000 + myForkInfo.openTwoTargets.length * 18000;
    }
    if (oppMills > 0) {
      return 340000 + oppMills * 48000 + myForkInfo.openTwoTargets.length * 16000;
    }
  }

  let score = getMorrisNodeWeight(nodeId) * 190;

  const blueprint = MorrisLearner.getActiveBlueprintNodes();
  const bpIdx = blueprint.indexOf(nodeId);
  if (bpIdx !== -1 && bpIdx < 8) {
    score += (9 - bpIdx) * 650;
  }
  const hFreq = (nodeId < MorrisLearner.humanNodeFreq.length && MorrisLearner.humanNodeFreq[nodeId]) || 0;
  if (hFreq > 0) {
    score += Math.min(3200, hFreq * 480);
  }

  let liberties = 0;
  let friendlyAdj = 0;
  for (const nb of Adjacency[nodeId]) {
    if (sim[nb] === 0) liberties++;
    else if (sim[nb] === aiP) friendlyAdj++;
  }
  if (liberties === 0) score -= 28000;
  else if (liberties === 1) score -= 5500;
  else score += liberties * 1450;

  for (const nb of Adjacency[nodeId]) {
    if (board[nb] === humanP) {
      let oppLib = 0;
      for (const onb of Adjacency[nb]) {
        if (sim[onb] === 0) oppLib++;
      }
      if (oppLib === 0) score += 18500;
      else if (oppLib === 1) score += 6200;
    }
  }

  if (!landingMillForbidden) {
    // Offensive & Defensive Double-Threat Fork Detection
    const myNewTwos = myForkInfo.openTwoTargets.length;
    const oppNewTwosIfOppDropsHere = oppForkInfo.openTwoTargets.length;

    score += myNewTwos * 16500;
    score += myForkInfo.loadedTargets.length * 14000;
    if (myNewTwos >= 2) {
      // Dropping here creates an unstoppable Double 2-in-a-Row Fork for AI!
      score += 135000;
    }
    if (oppNewTwosIfOppDropsHere >= 2) {
      // CRITICAL: `nodeId` is a Human Fork Point! If AI doesn't take it, Human drops here and creates a Double-Mill Fork!
      score += 125000 + oppNewTwosIfOppDropsHere * 15000;
    } else if (oppNewTwosIfOppDropsHere === 1) {
      score += 9500;
    }
  } else {
    // `forbid_mill` ("No Katar on Landing") specialized Grandmaster heuristics:
    const oppRawMillsHere = oppForkInfo.rawMillCount;
    const pairs = NodeMillPairs[nodeId] || [];

    // 1. Plugging an opponent's 2-in-a-row `[h1, h2, nodeId]`
    if (oppRawMillsHere > 0) {
      for (let i = 0; i < pairs.length; i++) {
        const [o1, o2, lIdx] = pairs[i];
        if (board[o1] === humanP && board[o2] === humanP) {
          const line = MillLines[lIdx];
          const hasSlider = hasReadySliderForMill(nodeId, line, humanP, board);
          let emptySliderSpots = 0;
          for (const nb of Adjacency[nodeId]) {
            if (!line.includes(nb) && board[nb] === 0) emptySliderSpots++;
          }
          if (hasSlider) {
            // Opponent already has a ready slider into `nodeId`!
            score += (resHuman <= 4) ? 145000 : 88000;
          } else if (emptySliderSpots > 0) {
            // Opponent can drop a slider adjacent to `nodeId` unless we plug `nodeId`!
            score += (resHuman <= 4) ? 68000 : 38000;
          } else {
            score += 6000;
          }
        }
      }
    }

    // 2. Building AI's own Loaded Slide-Mills & Immune Targets
    score += myForkInfo.openTwoTargets.length * 9500;
    score += myForkInfo.loadedTargets.length * 44000;
    if (myForkInfo.loadedTargets.length >= 2) {
      score += 96000;
    }

    // IMMUNE TARGET THEOREM: If `empId` in `myForkInfo.openTwoTargets` is ALSO an opponent 2-in-a-row,
    // the opponent is legally FORBIDDEN from dropping on `empId` to block AI's mill!
    for (const empId of myForkInfo.openTwoTargets) {
      if (fastWouldCompleteMill(empId, humanP, board) > 0) {
        score += myForkInfo.loadedTargets.includes(empId) ? 75000 : 34000;
      }
    }

    // 3. Blocking Human from arming a Loaded Slide-Mill
    if (oppForkInfo.loadedTargets.length >= 2) {
      score += 92000;
    } else if (oppForkInfo.loadedTargets.length === 1) {
      score += 42000;
    }
  }

  return score;
}

function chooseBestMorrisDrop(allSteps, board, aiP, humanP, isAllAtOnce, resAi, resHuman, diff) {
  if (isAllAtOnce && diff !== 'easy' && resAi >= 1) {
    const forbidLandingMill = true;
    const beamWidth = diff === 'hardest' ? 16 : (diff === 'hard' ? 10 : 4);
    let beam = [{
      board: [...board],
      firstMove: null,
      learnedSum: 0,
      score: evaluateAllAtOnceBoard(board, aiP, humanP, resAi, resHuman)
    }];

    const stepsToPlan = diff === 'medium' ? Math.min(3, resAi) : resAi;
    for (let step = 0; step < stepsToPlan; step++) {
      const nextBeam = [];
      const seenKeys = new Set();
      const remAfter = resAi - step - 1;

      for (const state of beam) {
        const emptyIds = [];
        const nonMillIds = [];
        for (let i = 0; i < Nodes.length; i++) {
          if (state.board[i] === 0) {
            emptyIds.push(i);
            if (forbidLandingMill) {
              if (fastWouldCompleteMill(i, aiP, state.board) === 0) {
                nonMillIds.push(i);
              }
            }
          }
        }
        const legalIds = (forbidLandingMill && nonMillIds.length > 0) ? nonMillIds : emptyIds;
        for (const nid of legalIds) {
          const nb = [...state.board];
          nb[nid] = aiP;
          const key = computeMorrisStateKey(nb, 0, 0, aiP);
          if (seenKeys.has(key)) continue;
          seenKeys.add(key);
          const stepMove = { from: -1, to: nid, type: 'drop' };
          const firstMv = state.firstMove || stepMove;
          const stepLearned = (diff === 'hardest')
            ? MorrisLearner.getHardestBonus(state.board, stepMove, aiP, resAi - step, resHuman)
            : MorrisLearner.getBonus(state.board, stepMove, aiP, resAi - step, resHuman);
          const newLearnedSum = state.learnedSum + stepLearned * (step === 0 ? 1.5 : 0.6);
          const jitter = (diff === 'medium' ? (Math.random() * 800 - 400) : 0);
          const sc = evaluateAllAtOnceBoard(nb, aiP, humanP, remAfter, resHuman) + newLearnedSum + jitter;
          nextBeam.push({ board: nb, firstMove: firstMv, learnedSum: newLearnedSum, score: sc });
        }
      }

      if (nextBeam.length === 0) break;
      nextBeam.sort((a, b) => b.score - a.score);
      beam = nextBeam.slice(0, beamWidth);
    }

    if (resHuman === 0 && resAi <= 4 && (diff === 'hard' || diff === 'hardest') && beam.length > 0) {
      if (MorrisTT.size > 120000) MorrisTT.clear();
      morrisSearchAborted = false;
      morrisSearchDeadline = performance.now() + (diff === 'hardest' ? 650 : 380);
      let bestCand = beam[0];
      let bestTotal = -Infinity;
      for (const cand of beam.slice(0, 7)) {
        const mmVal = minimaxMorris(
          cand.board,
          0,
          0,
          diff === 'hardest' ? 7 : 5,
          -Infinity,
          Infinity,
          humanP,
          aiP,
          humanP,
          new Set()
        );
        const combined = cand.score + mmVal * 10;
        if (combined > bestTotal) {
          bestTotal = combined;
          bestCand = cand;
        }
      }
      if (bestCand && bestCand.firstMove) return bestCand.firstMove;
    }

    if (beam[0] && beam[0].firstMove) {
      return beam[0].firstMove;
    }
  }

  const scored = [];
  for (const m of allSteps) {
    const learned = (diff === 'hardest')
      ? MorrisLearner.getHardestBonus(board, m, aiP, resAi, resHuman)
      : MorrisLearner.getBonus(board, m, aiP, resAi, resHuman);
    const s1 = scoreMorrisPlacement(m.to, board, aiP, humanP, isAllAtOnce, resAi, resHuman) + learned;
    scored.push({ move: m, score: s1 });
  }
  scored.sort((a, b) => b.score - a.score);
  if (diff === 'easy') {
    const easyPool = scored.slice(0, Math.min(5, scored.length));
    return easyPool[Math.floor(Math.random() * easyPool.length)].move;
  }
  if (diff === 'medium') {
    const pool = scored.slice(0, Math.min(2, scored.length));
    return pool[Math.floor(Math.random() * pool.length)].move;
  }
  return scored[0].move;
}

function evaluateMorrisBoardState(board, res1, res2, turnPlayer, aiP, humanP) {
  ensureMorrisTopologyCache();
  const res = { 1: res1, 2: res2 };
  const aiTotal = countPlayerTotalPieces(aiP, board, res);
  const hmTotal = countPlayerTotalPieces(humanP, board, res);

  if (hmTotal <= 2) return 95000;
  if (aiTotal <= 2) return -95000;

  const forbidLandingMill = (GameState.morrisDropOrder === 'all_at_once' || GameState.morrisDropMillRule === 'forbid_mill');
  const protectMills = (GameState.morrisMillRemovalRule === 'protect_mills');
  const aiCanFly = canPlayerFlyOnBoard(aiP, board, res);
  const hmCanFly = canPlayerFlyOnBoard(humanP, board, res);

  let score = (aiTotal - hmTotal) * 6800;
  if (hmTotal === 3 && res[humanP] === 0) score += hmCanFly ? 2600 : 4800;
  if (aiTotal === 3 && res[aiP] === 0) score -= aiCanFly ? 2600 : 4800;

  let aiRepeatableMills = 0, hmRepeatableMills = 0;
  let aiLockedMills = 0, hmLockedMills = 0;
  let aiSeeSaw = 0, hmSeeSaw = 0;
  let aiPinnedOppMills = 0, hmPinnedAiMills = 0;
  let aiBlockedTwo = 0, hmBlockedTwo = 0;

  const aiOpenEmptySet = new Set();
  const hmOpenEmptySet = new Set();
  const aiReadyEmptySet = new Set();
  const hmReadyEmptySet = new Set();
  const aiUncontestedReadySet = new Set();
  const hmUncontestedReadySet = new Set();
  const aiTwoShare = new Int32Array(Nodes.length);
  const hmTwoShare = new Int32Array(Nodes.length);

  for (let lIdx = 0; lIdx < MillLines.length; lIdx++) {
    const line = MillLines[lIdx];
    let a = 0, h = 0, e = 0, empNode = -1;
    for (let k = 0; k < 3; k++) {
      const id = line[k];
      const v = board[id];
      if (v === aiP) a++;
      else if (v === humanP) h++;
      else { e++; empNode = id; }
    }

    if (a === 3) {
      let canSafelyOpen = false;
      let isPinnedByHuman = false;
      for (let k = 0; k < 3; k++) {
        const id = line[k];
        let hasEmptyOut = false;
        let oppAdj = false;
        for (const nb of Adjacency[id]) {
          if (nb !== line[0] && nb !== line[1] && nb !== line[2]) {
            if (board[nb] === 0) {
              hasEmptyOut = true;
              if (fastWouldCompleteMill(nb, aiP, board) > 0) {
                aiSeeSaw++;
              }
            } else if (board[nb] === humanP) {
              oppAdj = true;
            }
          }
        }
        if (hasEmptyOut && !oppAdj && !hmCanFly) canSafelyOpen = true;
        if (hasEmptyOut && oppAdj) isPinnedByHuman = true;
      }
      if (canSafelyOpen) aiRepeatableMills++;
      else aiLockedMills++;
      if (isPinnedByHuman && protectMills) hmPinnedAiMills++;
    } else if (h === 3) {
      let canSafelyOpen = false;
      let isPinnedByAi = false;
      for (let k = 0; k < 3; k++) {
        const id = line[k];
        let hasEmptyOut = false;
        let aiAdj = false;
        for (const nb of Adjacency[id]) {
          if (nb !== line[0] && nb !== line[1] && nb !== line[2]) {
            if (board[nb] === 0) {
              hasEmptyOut = true;
              if (fastWouldCompleteMill(nb, humanP, board) > 0) {
                hmSeeSaw++;
              }
            } else if (board[nb] === aiP) {
              aiAdj = true;
            }
          }
        }
        if (hasEmptyOut && !aiAdj && !aiCanFly) canSafelyOpen = true;
        if (hasEmptyOut && aiAdj) isPinnedByAi = true;
      }
      if (canSafelyOpen) hmRepeatableMills++;
      else hmLockedMills++;
      if (isPinnedByAi && protectMills) aiPinnedOppMills++;
    } else if (a === 2 && e === 1) {
      aiOpenEmptySet.add(empNode);
      for (let k = 0; k < 3; k++) {
        const id = line[k];
        if (board[id] === aiP) aiTwoShare[id]++;
      }
      if (canPlayerCloseMillAt(empNode, line, aiP, board, res)) {
        aiReadyEmptySet.add(empNode);
        let oppCanBlock = false;
        if (res[humanP] > 0) {
          // In forbidLandingMill mode, if `empNode` would complete a human mill, human CANNOT drop on `empNode`!
          oppCanBlock = !(forbidLandingMill && fastWouldCompleteMill(empNode, humanP, board) > 0);
        } else if (hmCanFly) {
          oppCanBlock = true;
        } else {
          for (const nb of Adjacency[empNode]) {
            if (board[nb] === humanP) {
              oppCanBlock = true;
              break;
            }
          }
        }
        if (!oppCanBlock) aiUncontestedReadySet.add(empNode);
      }
    } else if (h === 2 && e === 1) {
      hmOpenEmptySet.add(empNode);
      for (let k = 0; k < 3; k++) {
        const id = line[k];
        if (board[id] === humanP) hmTwoShare[id]++;
      }
      if (canPlayerCloseMillAt(empNode, line, humanP, board, res)) {
        hmReadyEmptySet.add(empNode);
        let aiCanBlock = false;
        if (res[aiP] > 0) {
          aiCanBlock = !(forbidLandingMill && fastWouldCompleteMill(empNode, aiP, board) > 0);
        } else if (aiCanFly) {
          aiCanBlock = true;
        } else {
          for (const nb of Adjacency[empNode]) {
            if (board[nb] === aiP) {
              aiCanBlock = true;
              break;
            }
          }
        }
        if (!aiCanBlock) hmUncontestedReadySet.add(empNode);
      }
    } else if (a === 2 && h === 1) {
      hmBlockedTwo++;
    } else if (h === 2 && a === 1) {
      aiBlockedTwo++;
    }
  }

  let aiForks = 0, hmForks = 0;
  let aiMob = 0, hmMob = 0;
  let aiTrapped = 0, hmTrapped = 0;

  for (let i = 0; i < Nodes.length; i++) {
    if (aiTwoShare[i] >= 2) aiForks++;
    if (hmTwoShare[i] >= 2) hmForks++;

    const occ = board[i];
    if (occ === aiP) {
      score += getMorrisNodeWeight(i);
      let degEmpty = 0;
      for (const nb of Adjacency[i]) if (board[nb] === 0) degEmpty++;
      aiMob += degEmpty;
      if (degEmpty === 0 && !aiCanFly) aiTrapped++;
    } else if (occ === humanP) {
      score -= getMorrisNodeWeight(i);
      let degEmpty = 0;
      for (const nb of Adjacency[i]) if (board[nb] === 0) degEmpty++;
      hmMob += degEmpty;
      if (degEmpty === 0 && !hmCanFly) hmTrapped++;
    }
  }

  if (res1 === 0 && res2 === 0) {
    if (!hmCanFly && hmMob === 0) return 93000;
    if (!aiCanFly && aiMob === 0) return -93000;
    if (!hmCanFly) {
      if (hmMob === 1) score += 7200;
      else if (hmMob === 2) score += 3600;
    }
    if (!aiCanFly) {
      if (aiMob === 1) score -= 7200;
      else if (aiMob === 2) score -= 3600;
    }
  }

  score += (aiSeeSaw - hmSeeSaw) * 9500;
  score += (aiRepeatableMills - hmRepeatableMills) * 3400;
  score += (aiLockedMills - hmLockedMills) * (protectMills ? 1250 : 600);
  score += (aiPinnedOppMills - hmPinnedAiMills) * 1800;
  score += (aiUncontestedReadySet.size - hmUncontestedReadySet.size) * 5800;
  score += ((aiReadyEmptySet.size - aiUncontestedReadySet.size) - (hmReadyEmptySet.size - hmUncontestedReadySet.size)) * 2200;
  score += (aiOpenEmptySet.size - hmOpenEmptySet.size) * 750;
  score += (aiForks - hmForks) * 3400;
  score += (aiBlockedTwo - hmBlockedTwo) * 420;
  score += (aiMob - hmMob) * 180;
  score += (hmTrapped - aiTrapped) * 1500;

  // Turn-aware immediate threat evaluation
  if (turnPlayer === aiP) {
    if (aiReadyEmptySet.size >= 1) score += 8200;
    if (aiReadyEmptySet.size >= 2) score += 6500;
    // If Human has >= 2 distinct ready threats, AI can only block 1 on this turn unless AI forms a mill!
    if (hmReadyEmptySet.size >= 2 && aiReadyEmptySet.size === 0) score -= 9500;
    if (hmUncontestedReadySet.size >= 1 && aiReadyEmptySet.size === 0) score -= 7800;
  } else {
    if (hmReadyEmptySet.size >= 1) score -= 8200;
    if (hmReadyEmptySet.size >= 2) score -= 6500;
    if (aiReadyEmptySet.size >= 2 && hmReadyEmptySet.size === 0) score += 9500;
    if (aiUncontestedReadySet.size >= 1 && hmReadyEmptySet.size === 0) score += 7800;
  }

  return score;
}

function expandMorrisMoveStates(board, res1, res2, move, player, aiP, humanP, branchRemovals = 2) {
  const baseBoard = [...board];
  let nRes1 = res1, nRes2 = res2;

  if (move.type === 'drop') {
    baseBoard[move.to] = player;
    if (player === 1) nRes1 = Math.max(0, nRes1 - 1);
    else nRes2 = Math.max(0, nRes2 - 1);
  } else {
    baseBoard[move.from] = 0;
    baseBoard[move.to] = player;
  }

  const forbidLandingMill = (GameState.morrisDropOrder === 'all_at_once' || GameState.morrisDropMillRule === 'forbid_mill');
  const formedCount = (move.type === 'drop' && forbidLandingMill) ? 0 : fastCountMillsAtNode(move.to, player, baseBoard);
  if (formedCount === 0) {
    return [{ board: baseBoard, res1: nRes1, res2: nRes2, formedMill: false, removedId: -1 }];
  }

  const opp = player === 1 ? 2 : 1;
  const victims = getTopMorrisRemovals(baseBoard, player, opp, nRes1, nRes2, branchRemovals);
  if (victims.length === 0) {
    return [{ board: baseBoard, res1: nRes1, res2: nRes2, formedMill: true, removedId: -1 }];
  }

  return victims.map((vid) => {
    const b2 = [...baseBoard];
    b2[vid] = 0;
    return { board: b2, res1: nRes1, res2: nRes2, formedMill: true, removedId: vid };
  });
}

function encodeMorrisMoveKey(m) {
  if (!m) return 0;
  if (m.type === 'drop') return 1000 + m.to;
  if (m.type === 'step') return ((m.from + 1) * 25) + m.to;
  if (m.type === 'remove_opponent') return 2000 + m.capturedId;
  return 0;
}

function orderMorrisMoves(moves, board, player, opp, res1, res2, applyRootAntiLoop = false, depth = 0, ttBestMoveKey = 0) {
  ensureMorrisTopologyCache();
  const res = { 1: res1, 2: res2 };
  const scored = [];
  const canFly = canPlayerFlyOnBoard(player, board, res);
  const killerPair = MorrisKillerMoves[depth] || null;
  const histTbl = MorrisHistoryTable[player] || null;

  for (const m of moves) {
    if (m.type === 'step' && !canFly && !Adjacency[m.from].has(m.to)) {
      continue;
    }
    const mKey = encodeMorrisMoveKey(m);
    const pvBonus = (ttBestMoveKey && mKey === ttBestMoveKey) ? 600000 : 0;
    const killerBonus = (killerPair && (mKey === killerPair[0] || mKey === killerPair[1])) ? 35000 : 0;
    const histBonus = (histTbl && mKey > 0 && mKey < histTbl.length) ? Math.min(18000, histTbl[mKey]) : 0;

    if (m.type === 'drop') {
      const p = scoreMorrisPlacement(m.to, board, player, opp, GameState.morrisDropOrder === 'all_at_once', res[player], res[opp])
        + pvBonus + killerBonus + histBonus;
      scored.push({ move: m, mKey, priority: p, isForbiddenLoop: false });
      continue;
    }

    let priority = getMorrisNodeWeight(m.to) * 10 + pvBonus + killerBonus + histBonus;
    const sim = [...board];
    sim[m.from] = 0;
    sim[m.to] = player;

    const myMillsCount = fastCountMillsAtNode(m.to, player, sim);
    const wasInMill = fastCountMillsAtNode(m.from, player, board) > 0;

    if (myMillsCount > 0) {
      priority += 110000 * myMillsCount;
      if (wasInMill) priority += 125000; // See-saw double mill!
    }

    if (wasInMill && myMillsCount === 0) {
      let oppCanEnterFrom = canPlayerFlyOnBoard(opp, board, res);
      if (!oppCanEnterFrom) {
        for (const nb of Adjacency[m.from]) {
          if (board[nb] === opp) { oppCanEnterFrom = true; break; }
        }
      }
      if (!oppCanEnterFrom) priority += 36000; // Safe opening of running mill
      else priority -= 34000;
    }

    // Blocking opponent 1-step mill at `m.to`
    const oppMillsAtTo = fastWouldCompleteMill(m.to, opp, board);
    if (oppMillsAtTo > 0) {
      const toPairs = NodeMillPairs[m.to] || [];
      let hasSlider = canPlayerFlyOnBoard(opp, board, res);
      for (let i = 0; i < toPairs.length && !hasSlider; i++) {
        const [o1, o2, lIdx] = toPairs[i];
        if (board[o1] === opp && board[o2] === opp) {
          if (hasReadySliderForMill(m.to, MillLines[lIdx], opp, board)) hasSlider = true;
        }
      }
      priority += hasSlider ? 82000 : 22000;
    }

    // Penalty for vacating `m.from` when `m.from` was blocking an opponent 2-in-a-row!
    if (myMillsCount === 0) {
      const oppMillsAtFrom = fastWouldCompleteMill(m.from, opp, sim);
      if (oppMillsAtFrom > 0) {
        const fromPairs = NodeMillPairs[m.from] || [];
        let oppReady = canPlayerFlyOnBoard(opp, sim, res);
        for (let i = 0; i < fromPairs.length && !oppReady; i++) {
          const [o1, o2, lIdx] = fromPairs[i];
          if (sim[o1] === opp && sim[o2] === opp) {
            if (hasReadySliderForMill(m.from, MillLines[lIdx], opp, sim)) oppReady = true;
          }
        }
        if (oppReady) priority -= 86000;
      }
    }

    // Creating our own 1-step ready mill
    const toPairs = NodeMillPairs[m.to] || [];
    let createdReady = 0;
    for (let i = 0; i < toPairs.length; i++) {
      const [o1, o2, lIdx] = toPairs[i];
      const v1 = sim[o1], v2 = sim[o2];
      if ((v1 === player && v2 === 0) || (v2 === player && v1 === 0)) {
        const emp = v1 === 0 ? o1 : o2;
        if (canPlayerCloseMillAt(emp, MillLines[lIdx], player, sim, res)) {
          createdReady++;
          priority += 28000;
        } else {
          priority += 6500;
        }
      }
    }
    if (createdReady >= 2) priority += 55000; // Double-mill slide fork!

    let myLib = 0;
    for (const nb of Adjacency[m.to]) {
      if (sim[nb] === 0) myLib++;
    }
    if (myLib === 0 && myMillsCount === 0 && !canFly) priority -= 16000;
    else priority += myLib * 650;

    for (const nb of Adjacency[m.to]) {
      if (board[nb] === opp) {
        let oppLib = 0;
        for (const onb of Adjacency[nb]) if (sim[onb] === 0) oppLib++;
        if (oppLib === 0) priority += 16500;
        else if (oppLib === 1) priority += 5200;
        if (GameState.morrisMillRemovalRule === 'protect_mills' && fastCountMillsAtNode(nb, opp, board) > 0) {
          priority += 8500; // Pinning opponent's closed mill
        }
      }
    }

    let isForbiddenLoop = false;
    if (applyRootAntiLoop) {
      const loopInfo = LoopTracker.evaluateLoopPenalty(m, board, sim, player, res1, res2, myMillsCount > 0);
      priority -= loopInfo.penalty * 4;
      priority += loopInfo.breakthroughBonus * 4;
      isForbiddenLoop = loopInfo.isForbiddenLoop;
    }

    scored.push({ move: m, mKey, priority, isForbiddenLoop });
  }

  scored.sort((a, b) => b.priority - a.priority);
  if (applyRootAntiLoop && scored.length > 1) {
    const nonLooping = scored.filter((s) => !s.isForbiddenLoop);
    if (nonLooping.length > 0) {
      const looping = scored.filter((s) => s.isForbiddenLoop);
      return [...nonLooping, ...looping].map((s) => s.move);
    }
  }
  return scored.map((s) => s.move);
}

function computeMorrisStateKey(board, res1, res2, turnPlayer) {
  let h1 = 0, h2 = 0;
  const len = Math.min(board.length, 24);
  for (let i = 0; i < 12 && i < len; i++) h1 = (h1 * 3) + board[i];
  for (let i = 12; i < len; i++) h2 = (h2 * 3) + board[i];
  return `${turnPlayer}:${res1}:${res2}:${h1}:${h2}`;
}

// Tactical Mill Quiescence Search at depth <= 0 to eliminate Horizon Effect on imminent mills
function quiesceMorris(board, res1, res2, qDepth, alpha, beta, turnPlayer, aiP, humanP) {
  const standPat = evaluateMorrisBoardState(board, res1, res2, turnPlayer, aiP, humanP);
  if (qDepth <= 0 || Math.abs(standPat) >= 90000) {
    return standPat;
  }
  if (morrisSearchDeadline && performance.now() > morrisSearchDeadline) {
    morrisSearchAborted = true;
    return standPat;
  }

  const res = { 1: res1, 2: res2 };
  const forbidLandingMill = (GameState.morrisDropOrder === 'all_at_once' || GameState.morrisDropMillRule === 'forbid_mill');
  if ((res[turnPlayer] || 0) > 0 && forbidLandingMill) {
    return standPat;
  }

  const rawMoves = getAllLegalActionsForPlayer(turnPlayer, board, res).allSteps;
  if (rawMoves.length === 0) {
    return turnPlayer === aiP ? -93000 : 93000;
  }

  // Filter ONLY moves that immediately complete a 3-in-a-row Katar mill on this turn
  const millMoves = [];
  for (let i = 0; i < rawMoves.length; i++) {
    const m = rawMoves[i];
    if (m.type === 'drop') {
      if (fastWouldCompleteMill(m.to, turnPlayer, board) > 0) millMoves.push(m);
    } else {
      const prev = board[m.from];
      board[m.from] = 0;
      const forms = fastWouldCompleteMill(m.to, turnPlayer, board) > 0;
      board[m.from] = prev;
      if (forms) millMoves.push(m);
    }
  }

  if (millMoves.length === 0) {
    return standPat;
  }

  const isMax = (turnPlayer === aiP);
  const opp = turnPlayer === 1 ? 2 : 1;
  let bestVal = standPat;
  if (isMax) {
    if (bestVal >= beta) return bestVal;
    if (bestVal > alpha) alpha = bestVal;
  } else {
    if (bestVal <= alpha) return bestVal;
    if (bestVal < beta) beta = bestVal;
  }

  for (let i = 0; i < Math.min(4, millMoves.length); i++) {
    const mv = millMoves[i];
    const states = expandMorrisMoveStates(board, res1, res2, mv, turnPlayer, aiP, humanP, 1);
    for (const st of states) {
      const nextTurn = (GameState.morrisDropOrder === 'all_at_once' && (turnPlayer === 1 ? st.res1 : st.res2) > 0)
        ? turnPlayer
        : opp;
      const ev = quiesceMorris(st.board, st.res1, st.res2, qDepth - 1, alpha, beta, nextTurn, aiP, humanP);
      if (morrisSearchAborted) return bestVal;
      if (isMax) {
        if (ev > bestVal) bestVal = ev;
        if (bestVal > alpha) alpha = bestVal;
      } else {
        if (ev < bestVal) bestVal = ev;
        if (bestVal < beta) beta = bestVal;
      }
      if (beta <= alpha) break;
    }
    if (beta <= alpha) break;
  }

  return bestVal;
}

function minimaxMorris(board, res1, res2, depth, alpha, beta, turnPlayer, aiP, humanP, pathSet = null) {
  if (morrisSearchDeadline && performance.now() > morrisSearchDeadline) {
    morrisSearchAborted = true;
    return evaluateMorrisBoardState(board, res1, res2, turnPlayer, aiP, humanP);
  }

  const res = { 1: res1, 2: res2 };
  const aiTotal = countPlayerTotalPieces(aiP, board, res);
  const hmTotal = countPlayerTotalPieces(humanP, board, res);
  if (hmTotal <= 2) return 95000 + depth * 250;
  if (aiTotal <= 2) return -95000 - depth * 250;

  const ttKey = computeMorrisStateKey(board, res1, res2, turnPlayer);
  if (pathSet && pathSet.has(ttKey)) {
    return 0;
  }
  if (res1 === 0 && res2 === 0) {
    const sig = LoopTracker.computeSignature(board, res, null);
    const matchReps = LoopTracker.stateCounts.get(sig) || 0;
    if (matchReps >= 2) {
      return -18000;
    }
  }

  if (depth <= 0) {
    return quiesceMorris(board, res1, res2, 2, alpha, beta, turnPlayer, aiP, humanP);
  }

  let ttBestMoveKey = 0;
  const cached = MorrisTT.get(ttKey);
  if (cached) {
    ttBestMoveKey = cached.bestMoveKey || 0;
    if (cached.depth >= depth) {
      if (cached.flag === 0) return cached.val;
      if (cached.flag === 1 && cached.val > alpha) alpha = cached.val;
      else if (cached.flag === 2 && cached.val < beta) beta = cached.val;
      if (alpha >= beta) return cached.val;
    }
  }

  const rawMoves = getAllLegalActionsForPlayer(turnPlayer, board, res).allSteps;
  if (rawMoves.length === 0) {
    return turnPlayer === aiP ? (-93000 - depth * 200) : (93000 + depth * 200);
  }

  const opp = turnPlayer === 1 ? 2 : 1;
  const ordered = orderMorrisMoves(rawMoves, board, turnPlayer, opp, res1, res2, false, depth, ttBestMoveKey);
  const isHardest = (GameState.aiDifficulty === 'hardest');
  const maxMoves = isHardest
    ? (depth >= 7 ? 14 : (depth >= 4 ? 18 : 24))
    : (depth >= 5 ? 12 : (depth >= 3 ? 14 : 16));
  const pool = ordered.slice(0, maxMoves);
  const remBranch = isHardest ? (depth >= 4 ? 3 : 2) : (depth >= 3 ? 2 : 1);

  let nextPathSet = pathSet;
  if (res1 === 0 && res2 === 0) {
    nextPathSet = new Set(pathSet || []);
    nextPathSet.add(ttKey);
  }

  const alphaOrig = alpha;
  const betaOrig = beta;
  const isMax = (turnPlayer === aiP);
  let bestVal = isMax ? -Infinity : Infinity;
  let bestMoveKey = ttBestMoveKey;

  for (let i = 0; i < pool.length; i++) {
    const mv = pool[i];
    const mvKey = encodeMorrisMoveKey(mv);
    const states = expandMorrisMoveStates(board, res1, res2, mv, turnPlayer, aiP, humanP, remBranch);
    for (let sIdx = 0; sIdx < states.length; sIdx++) {
      const st = states[sIdx];
      const nextTurn = (GameState.morrisDropOrder === 'all_at_once' && (turnPlayer === 1 ? st.res1 : st.res2) > 0)
        ? turnPlayer
        : opp;
      const ev = minimaxMorris(st.board, st.res1, st.res2, depth - 1, alpha, beta, nextTurn, aiP, humanP, nextPathSet);
      if (morrisSearchAborted) return bestVal === -Infinity || bestVal === Infinity ? ev : bestVal;

      if (isMax) {
        if (ev > bestVal) {
          bestVal = ev;
          bestMoveKey = mvKey;
        }
        if (bestVal > alpha) alpha = bestVal;
      } else {
        if (ev < bestVal) {
          bestVal = ev;
          bestMoveKey = mvKey;
        }
        if (bestVal < beta) beta = bestVal;
      }
      if (beta <= alpha) {
        if (!st.formedMill) {
          const kp = MorrisKillerMoves[depth] || [0, 0];
          if (kp[0] !== mvKey) {
            kp[1] = kp[0];
            kp[0] = mvKey;
            MorrisKillerMoves[depth] = kp;
          }
          const hTbl = MorrisHistoryTable[turnPlayer];
          if (hTbl && mvKey > 0 && mvKey < hTbl.length) {
            hTbl[mvKey] += depth * depth * 40;
          }
        }
        break;
      }
    }
    if (beta <= alpha) break;
  }

  if (!morrisSearchAborted && MorrisTT.size < 160000) {
    let flag = 0;
    if (bestVal <= alphaOrig) flag = 2;
    else if (bestVal >= betaOrig) flag = 1;
    MorrisTT.set(ttKey, { depth, val: bestVal, flag, bestMoveKey });
  }

  return bestVal;
}

function computeBestLocalMorrisAction(aiP = (GameState.aiPlayerRole || 2)) {
  ensureMorrisTopologyCache();
  const curRuleSig = getMorrisRuleSignature();
  if (curRuleSig !== morrisLastRuleSig) {
    MorrisTT.clear();
    morrisLastRuleSig = curRuleSig;
  }

  const humanP = aiP === 1 ? 2 : 1;
  const diff = GameState.aiDifficulty;

  if (GameState.morrisPendingRemove) {
    const candidates = getRemovableOpponentNodes(humanP);
    if (candidates.length === 0) return null;
    if (diff === 'easy') {
      const pick = candidates[Math.floor(Math.random() * candidates.length)];
      return { bestAction: { type: 'remove_opponent', capturedId: pick }, ranked: candidates.map((c) => ({ action: { type: 'remove_opponent', capturedId: c }, score: 0 })) };
    }
    if (diff === 'medium') {
      const bestMid = pickBestMorrisRemoval(GameState.board, aiP, humanP);
      const act = { type: 'remove_opponent', capturedId: bestMid !== -1 ? bestMid : candidates[0] };
      return { bestAction: act, ranked: candidates.map((c) => ({ action: { type: 'remove_opponent', capturedId: c }, score: scoreMorrisRemovalTarget(c, GameState.board, aiP, humanP) })) };
    }

    if (MorrisTT.size > 140000) MorrisTT.clear();
    morrisSearchAborted = false;
    const intel = MorrisLearner.getIntelligenceLevel();
    morrisSearchDeadline = performance.now() + (diff === 'hardest' ? 450 : 280);

    let bestRem = candidates[0];
    let bestVal = -Infinity;
    const lookDepth = diff === 'hardest' ? (6 + Math.min(2, intel.depthBonus)) : 5;
    const ranked = [];

    for (const cid of candidates) {
      const simBoard = [...GameState.board];
      simBoard[cid] = 0;
      const remAct = { type: 'remove_opponent', capturedId: cid };
      const learned = (diff === 'hardest')
        ? MorrisLearner.getHardestBonus(GameState.board, remAct, aiP, GameState.reserves[aiP], GameState.reserves[humanP])
        : MorrisLearner.getBonus(GameState.board, remAct, aiP, GameState.reserves[aiP], GameState.reserves[humanP]);
      const immediateScore = scoreMorrisRemovalTarget(cid, GameState.board, aiP, humanP, GameState.reserves[1], GameState.reserves[2]);
      const nextTurn = (GameState.morrisDropOrder === 'all_at_once' && GameState.reserves[aiP] > 0) ? aiP : humanP;
      const futureVal = minimaxMorris(
        simBoard,
        GameState.reserves[1],
        GameState.reserves[2],
        lookDepth,
        -Infinity,
        Infinity,
        nextTurn,
        aiP,
        humanP,
        new Set()
      );
      const total = futureVal + immediateScore * 0.08 + learned * 0.4;
      ranked.push({ action: remAct, score: Math.round(total) });
      if (total > bestVal) {
        bestVal = total;
        bestRem = cid;
      }
    }
    ranked.sort((a, b) => b.score - a.score);
    return { bestAction: { type: 'remove_opponent', capturedId: bestRem }, ranked };
  }

  const { allSteps } = getAllLegalActionsForPlayer(aiP);
  if (allSteps.length === 0) return null;

  const isAllAtOnce = (GameState.morrisDropOrder === 'all_at_once');

  // Use specialized full-sequence beam planner for all_at_once drops, or easy/medium drops
  if (allSteps[0].type === 'drop' && (isAllAtOnce || diff === 'easy' || diff === 'medium')) {
    const chosenDrop = chooseBestMorrisDrop(
      allSteps,
      GameState.board,
      aiP,
      humanP,
      isAllAtOnce,
      GameState.reserves[aiP],
      GameState.reserves[humanP],
      diff
    );
    const rankedDrops = allSteps.map((m) => ({
      action: m,
      score: Math.round(scoreMorrisPlacement(m.to, GameState.board, aiP, humanP, isAllAtOnce, GameState.reserves[aiP], GameState.reserves[humanP]))
    })).sort((a, b) => b.score - a.score);
    return { bestAction: chosenDrop, ranked: rankedDrops };
  }

  const orderedMoves = orderMorrisMoves(allSteps, GameState.board, aiP, humanP, GameState.reserves[1], GameState.reserves[2], true, 0, 0);
  if (orderedMoves.length === 0) return null;

  if (diff === 'easy') {
    const pick = Math.random() < 0.72
      ? orderedMoves[Math.floor(Math.random() * Math.min(5, orderedMoves.length))]
      : orderedMoves[0];
    return { bestAction: pick, ranked: orderedMoves.map((m, i) => ({ action: m, score: 100 - i })) };
  }

  if (diff === 'medium') {
    let bestMed = orderedMoves[0];
    let bestMedScore = -Infinity;
    const ranked = [];
    for (const mv of orderedMoves.slice(0, 10)) {
      const states = expandMorrisMoveStates(GameState.board, GameState.reserves[1], GameState.reserves[2], mv, aiP, aiP, humanP, 1);
      const st = states[0];
      const loopInfo = LoopTracker.evaluateLoopPenalty(mv, GameState.board, st.board, aiP, st.res1, st.res2, st.formedMill);
      const val = evaluateMorrisBoardState(st.board, st.res1, st.res2, humanP, aiP, humanP)
        - loopInfo.penalty + loopInfo.breakthroughBonus + (Math.random() * 70 - 35);
      ranked.push({ action: mv, score: Math.round(val), isLoop: loopInfo.isForbiddenLoop });
      if (val > bestMedScore) {
        bestMedScore = val;
        bestMed = mv;
      }
    }
    ranked.sort((a, b) => b.score - a.score);
    return { bestAction: bestMed, ranked };
  }

  // HARD & HARDEST: Full Iterative Deepening Alpha-Beta + Quiescence + Transposition Table + Adaptive Brain
  if (MorrisTT.size > 140000) MorrisTT.clear();
  morrisSearchAborted = false;
  const intel = MorrisLearner.getIntelligenceLevel();
  const isDropPhase = (allSteps[0].type === 'drop');
  const isSmallBoard = (Nodes.length <= 16);
  const timeBudgetMs = diff === 'hardest'
    ? (isDropPhase ? 480 : (620 + intel.depthBonus * 110))
    : (isDropPhase ? 290 : 360);
  morrisSearchDeadline = performance.now() + timeBudgetMs;

  const maxDepth = diff === 'hardest'
    ? (isSmallBoard ? 12 : (isDropPhase ? (7 + Math.min(2, intel.depthBonus)) : (10 + intel.depthBonus)))
    : (isSmallBoard ? 8 : (isDropPhase ? 5 : 7));
  const rootPool = orderedMoves.slice(0, Math.min(isDropPhase ? 18 : 24, orderedMoves.length));
  let bestMove = rootPool[0];
  let latestScores = new Map();

  for (let d = 2; d <= maxDepth; d++) {
    let iterBestMove = rootPool[0];
    let iterBestVal = -Infinity;
    let rawAlpha = -Infinity;
    const iterMap = new Map();

    for (const mv of rootPool) {
      const states = expandMorrisMoveStates(GameState.board, GameState.reserves[1], GameState.reserves[2], mv, aiP, aiP, humanP, 3);
      let bestBranchVal = -Infinity;
      const learnedBias = (diff === 'hardest')
        ? MorrisLearner.getHardestBonus(GameState.board, mv, aiP, GameState.reserves[aiP], GameState.reserves[humanP])
        : MorrisLearner.getBonus(GameState.board, mv, aiP, GameState.reserves[aiP], GameState.reserves[humanP]);
      // Keep placement heuristic strictly scaled as a tie-breaker so it never overrides a 6800-pt bead capture or mill!
      const placementTieBreaker = isDropPhase
        ? Math.max(-1800, Math.min(2200, scoreMorrisPlacement(mv.to, GameState.board, aiP, humanP, false, GameState.reserves[aiP], GameState.reserves[humanP]) * 0.0045))
        : 0;

      for (const st of states) {
        const nextTurn = humanP;
        const millBonus = st.formedMill ? 1800 : 0;
        const loopInfo = LoopTracker.evaluateLoopPenalty(mv, GameState.board, st.board, aiP, st.res1, st.res2, st.formedMill);
        const rootAdditive = millBonus + placementTieBreaker + learnedBias - loopInfo.penalty + loopInfo.breakthroughBonus;
        // CRITICAL: Adjust alpha into raw minimax units so MIN node never suffers false beta-cutoffs!
        const childAlpha = (rawAlpha > -900000) ? (rawAlpha - rootAdditive - 100) : -Infinity;
        const mmVal = minimaxMorris(
          st.board,
          st.res1,
          st.res2,
          d - 1,
          childAlpha,
          Infinity,
          nextTurn,
          aiP,
          humanP,
          new Set()
        );
        const v = mmVal + rootAdditive;
        if (v > bestBranchVal) bestBranchVal = v;
        if (morrisSearchAborted) break;
      }

      if (morrisSearchAborted) break;
      iterMap.set(mv, Math.round(bestBranchVal));

      if (bestBranchVal > iterBestVal) {
        iterBestVal = bestBranchVal;
        iterBestMove = mv;
      }
      if (iterBestVal > rawAlpha) rawAlpha = iterBestVal;
    }

    if (!morrisSearchAborted) {
      bestMove = iterBestMove;
      latestScores = iterMap;
      rootPool.sort((a, b) => (latestScores.get(b) ?? -999999) - (latestScores.get(a) ?? -999999));
      if (iterBestVal >= 90000) break;
    } else {
      break;
    }
  }

  // Final strict anti-loop safeguard: if bestMove is a repeated loop and another root move doesn't lose immediately, break the loop!
  if (!isDropPhase && rootPool.length > 1) {
    const checkSim = [...GameState.board];
    checkSim[bestMove.from] = 0;
    checkSim[bestMove.to] = aiP;
    const formedM = fastCountMillsAtNode(bestMove.to, aiP, checkSim) > 0;
    const bestLoop = LoopTracker.evaluateLoopPenalty(bestMove, GameState.board, checkSim, aiP, GameState.reserves[1], GameState.reserves[2], formedM);
    if (bestLoop.isForbiddenLoop || bestLoop.repCount >= 2 || bestLoop.oscCount >= 2) {
      for (const alt of rootPool) {
        if (alt === bestMove) continue;
        const altSim = [...GameState.board];
        altSim[alt.from] = 0;
        altSim[alt.to] = aiP;
        const altMill = fastCountMillsAtNode(alt.to, aiP, altSim) > 0;
        const altLoop = LoopTracker.evaluateLoopPenalty(alt, GameState.board, altSim, aiP, GameState.reserves[1], GameState.reserves[2], altMill);
        const altScore = latestScores.get(alt) || 0;
        if (!altLoop.isForbiddenLoop && altLoop.repCount < 2 && altScore > -35000) {
          bestMove = alt;
          break;
        }
      }
    }
  }

  const ranked = rootPool.map((m) => ({
    action: m,
    score: latestScores.has(m) ? latestScores.get(m) : 0
  })).sort((a, b) => b.score - a.score);

  return { bestAction: bestMove, ranked };
}

function runNavakankariAI() {
  const aiP = GameState.aiPlayerRole || 2;
  const humanP = aiP === 1 ? 2 : 1;
  const result = computeBestLocalMorrisAction(aiP);
  if (!result || !result.bestAction) {
    if (GameState.morrisPendingRemove) finishTurnAndCheckWin(aiP, false, null);
    return;
  }
  MorrisLearner.recordStep(GameState.board, result.bestAction, aiP, GameState.reserves[aiP], GameState.reserves[humanP]);
  executeAction(result.bestAction, false);
}

